import { MakeLogicType, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { libraryObjectHref } from 'scenes/library/libraryUtils'
import { teamLogic } from 'scenes/teamLogic'

import { fileSystemSearchRetrieve } from '~/generated/core/api'
import type { FileSystemApi } from '~/generated/core/api.schemas'
import { FileSystemEntry } from '~/queries/schema/schema-general'

const OBJECT_LIMIT = 12

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayJumpBackPinLogicValues {
    currentProjectId: number | null // teamLogic
    pinSearchResults: FileSystemEntry[]
    pinSearchResultsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayJumpBackPinLogicActions {
    loadPinSearchResults: (search: string) => string
    loadPinSearchResultsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPinSearchResultsSuccess: (
        pinSearchResults: FileSystemEntry[],
        payload?: string
    ) => {
        payload?: string
        pinSearchResults: FileSystemEntry[]
    }
}

export type todayJumpBackPinLogicType = MakeLogicType<todayJumpBackPinLogicValues, todayJumpBackPinLogicActions>

export const todayJumpBackPinLogic = kea<todayJumpBackPinLogicType>([
    path(['scenes', 'project-homepage', 'today', 'todayJumpBackPinLogic']),
    connect(() => ({
        values: [teamLogic, ['currentProjectId']],
    })),
    loaders(({ values }) => ({
        pinSearchResults: [
            [] as FileSystemEntry[],
            {
                loadPinSearchResults: async (search: string, breakpoint) => {
                    await breakpoint(200)
                    if (!values.currentProjectId || !search.trim()) {
                        return []
                    }
                    let entries: FileSystemApi[]
                    try {
                        const response = await fileSystemSearchRetrieve(String(values.currentProjectId), {
                            search: search.trim(),
                            limit: OBJECT_LIMIT,
                        })
                        entries = response.results.map((result) => result.entry)
                    } catch {
                        entries = []
                    }
                    breakpoint()
                    return entries
                        .map(
                            (entry): FileSystemEntry => ({
                                id: entry.id,
                                path: entry.path,
                                type: entry.type,
                                ref: entry.ref ?? undefined,
                                href: entry.href ?? undefined,
                                last_viewed_at: entry.last_viewed_at,
                            })
                        )
                        .filter((entry) => libraryObjectHref(entry) !== null)
                },
            },
        ],
    })),
])
